import React, { useState } from 'react';
import './Career.css';

function CareerPage() {
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        phone: '',
        resume: null,
        message: ''
    });

    const handleChange = (e) => {
        const { name, value, files } = e.target;
        setFormData({
            ...formData,
            [name]: files ? files[0] : value
        });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        // Here you can handle the form submission
        alert('Application submitted!');
    };

    return (
        <div className="career-page">
            <section className="hero">
                <h1>Careers at Chintamani</h1>
                <p>Join a company that values innovation, integrity, and impact.</p>
            </section>

            <section className="why-join">
                <h2>Why Choose Chintamani?</h2>
                <ul>
                    <li>💡 Work on meaningful projects that contribute to national infrastructure and growth</li>
                    <li>🤝 Collaborative and growth-driven culture</li>
                    <li>📚 Continuous learning through internal sessions & external training</li>
                    <li>🌐 Opportunity to work with top-tier government and private clients</li>
                    <li>🏆 Transparent policies and career progression</li>
                </ul>
            </section>

            <section className="openings">
                <h2>Open Positions</h2>
                <div className="job-list">
                    {[
                        { role: 'Project Coordinator', dept: 'Operations', location: 'Ahmedabad', type: 'Full-Time' },
                        { role: 'Purchase Executive', dept: 'Procurement', location: 'Surat', type: 'Full-Time' },
                        { role: 'Business Development Executive', dept: 'Sales', location: 'Remote', type: 'Full-Time' },
                        { role: 'Store Assistant', dept: 'Warehouse', location: 'Gandhinagar', type: 'Full-Time' },
                    ].map((job, index) => (
                        <div className="job-card" key={index}>
                            <h3>{job.role}</h3>
                            <p><strong>Department:</strong> {job.dept}</p>
                            <p><strong>Location:</strong> {job.location}</p>
                            <p><strong>Type:</strong> {job.type}</p>
                            <button>Apply Now</button>
                        </div>
                    ))}
                </div>
            </section>

            <section className="life-at">
                <h2>Life at Chintamani</h2>
                <p>We foster a team-oriented, learning-first environment where every voice matters.</p>
                <blockquote>
                    “At Chintamani, I get to grow both technically and professionally while working on large-scale impactful projects.” – <em>Sneha, Project Engineer</em>
                </blockquote>
            </section>

            <section className="talent-pool">
                <h2>Didn’t Find a Suitable Role?</h2>
                <p>We’re always looking for talented individuals. Drop your resume and we’ll get back to you when a matching opportunity arises.</p>

                <form onSubmit={handleSubmit} className="application-form">
                    <input type="text" name="name" placeholder="Full Name" onChange={handleChange} required />
                    <input type="email" name="email" placeholder="Email" onChange={handleChange} required />
                    <input type="tel" name="phone" placeholder="Phone Number" onChange={handleChange} required />
                    <input type="file" name="resume" accept=".pdf" onChange={handleChange} required />
                    <textarea name="message" placeholder="Message or Cover Letter" onChange={handleChange}></textarea>
                    <button type="submit">Submit Application</button>
                </form>
            </section>

            <footer className="cta-footer">
                <p>Be part of something impactful. Shape your future with Chintamani.</p>
                <button>Explore Opportunities</button>
            </footer>
        </div>
    );
}

export default Career;
